# Controller to pull forward, clear the pinned contact, and straighten out
state = {
    'cleared': False,
    'fwd_dist': 0.0,
    'last_prog': None,
}

def control(obs):
    global state
    look_deg = -23.0
    prog = obs.get('progress', {}).get('covered', 0.0)
    hitch = obs.get('hitch_deg', 0.0)

    if state['last_prog'] is None:
        state['last_prog'] = prog

    d_prog = state['last_prog'] - prog
    if d_prog > 0:
        state['fwd_dist'] += d_prog
    state['last_prog'] = prog

    steer_fwd = 15.0

    if state['fwd_dist'] < 1.8:
        return {'steer_deg': steer_fwd, 'speed_mps': 1.0, 'look_deg': look_deg}

    target_hitch = 0.0
    hitch_err = hitch - target_hitch
    steer_rev = max(-30.0, min(30.0, 2.0 * hitch_err))
    return {'steer_deg': steer_rev, 'speed_mps': -0.6, 'look_deg': look_deg}

