state = {
    'phase': 'FWD_CLEAR',
    'start_t': None
}

def control(obs):
    global state
    import math
    t = obs.get('t', 0.0)
    look_deg = -23.0
    hitch = obs.get('hitch_deg', 0.0)
    rig = obs.get('rig', {})
    trailer_hdg = rig.get('trailer_heading_deg', -hitch)
    hold_s = obs.get('motion', {}).get('hold_s', 0.0)

    if state['phase'] == 'FWD_CLEAR':
        if hold_s > 0.0:
            return {'steer_deg': -15.0, 'speed_mps': 0.8, 'look_deg': look_deg}
        if state['start_t'] is None:
            state['start_t'] = t

        steer = -15.0
        if t - state['start_t'] > 2.8:
            state['phase'] = 'REVERSE_CORRIDOR'
            return {'steer_deg': 0.0, 'speed_mps': 0.0, 'look_deg': look_deg}
        return {'steer_deg': steer, 'speed_mps': 0.8, 'look_deg': look_deg}

    cam = obs.get('views', {}).get('camera', {})
    walls = cam.get('walls', [])

    pts = []
    for b_deg, d in walls:
        rel_angle_deg = (b_deg - (trailer_hdg + 180) + 180) % 360 - 180
        rel_rad = math.radians(rel_angle_deg)
        x = d * math.cos(rel_rad)
        y = d * math.sin(rel_rad)
        pts.append((x, y))

    left_pts = [p for p in pts if p[1] > 0 and 0.5 < p[0] < 5.0]
    right_pts = [p for p in pts if p[1] < 0 and 0.5 < p[0] < 5.0]

    target_hitch = 0.0
    if left_pts and right_pts:
        min_l = min(p[1] for p in left_pts)
        max_r = max(p[1] for p in right_pts)
        center_y = (min_l + max_r) / 2.0
        target_hitch = max(-15.0, min(15.0, center_y * 10.0))
    elif left_pts:
        min_l = min(p[1] for p in left_pts)
        if min_l < 1.3:
            target_hitch = -10.0
    elif right_pts:
        max_r = max(p[1] for p in right_pts)
        if max_r > -1.3:
            target_hitch = 10.0

    target_info = obs.get('target', {})
    if target_info.get('in_sight') and 'bearing_deg' in target_info:
        tb = target_info['bearing_deg']
        err = (tb - (trailer_hdg + 180) + 180) % 360 - 180
        target_hitch = max(-20.0, min(20.0, err * 0.6))

    hitch_err = hitch - target_hitch
    steer_rev = max(-30.0, min(30.0, 2.0 * hitch_err))

    return {'steer_deg': steer_rev, 'speed_mps': -0.6, 'look_deg': look_deg}

