import math

state = {
    'mode': 'PULL_FWD',
    'start_cov': None,
}

def control(obs):
    global state
    look_deg = -23.0
    cov = obs.get('progress', {}).get('covered', 0.0)
    hitch = obs.get('hitch_deg', 0.0)
    rig = obs.get('rig', {})
    trailer_hdg = rig.get('trailer_heading_deg', -hitch)

    if state['start_cov'] is None:
        state['start_cov'] = cov

    fwd_dist = state['start_cov'] - cov

    # Phase 1: Pull forward gently with moderate right steer (-8 deg) to shift away from left rail without hitting front-right rail
    if state['mode'] == 'PULL_FWD':
        if fwd_dist < 1.2:
            return {'steer_deg': -8.0, 'speed_mps': 0.6, 'look_deg': look_deg}
        else:
            state['mode'] = 'REVERSE'
            return {'steer_deg': 0.0, 'speed_mps': 0.0, 'look_deg': look_deg}

    # Phase 2: Reverse into right curve
    cam = obs.get('views', {}).get('camera', {})
    walls = cam.get('walls', [])

    target_hitch = -10.0  # gentle curve to the right

    if walls:
        pts = []
        for b_deg, d in walls:
            rel_angle = (b_deg - (trailer_hdg + 180) + 180) % 360 - 180
            rad = math.radians(rel_angle)
            x = d * math.cos(rad)
            y = d * math.sin(rad)
            pts.append((x, y))

        left_pts = [p for p in pts if p[1] > 0 and 0.2 < p[0] < 4.0]
        right_pts = [p for p in pts if p[1] < 0 and 0.2 < p[0] < 4.0]

        if left_pts:
            min_l = min(p[1] for p in left_pts)
            if min_l < 1.25:
                target_hitch = min(target_hitch, -16.0)
        if right_pts:
            max_r = max(p[1] for p in right_pts)
            if max_r > -1.1:
                target_hitch = max(target_hitch, 0.0)

    target_info = obs.get('target', {})
    if target_info.get('in_sight') and 'bearing_deg' in target_info:
        tb = target_info['bearing_deg']
        err = (tb - (trailer_hdg + 180) + 180) % 360 - 180
        target_hitch = max(-20.0, min(15.0, err * 0.6))

    hitch_err = hitch - target_hitch
    steer = max(-26.0, min(26.0, 1.8 * hitch_err))

    return {'steer_deg': steer, 'speed_mps': -0.5, 'look_deg': look_deg}

